brokenCode:
class SlugBuilder {
    static int slugBuilder(int value) {
        if (value <= 1) {
            return 0;
        }
        return value * slugBuilder(value - 1);
    }
}

solutionCode:
class SlugBuilder {
    static int slugBuilder(int value) {
        if (value <= 1) {
            return 1;
        }
        return value * slugBuilder(value - 1);
    }
}
